/* Deterministic SVG line art from the same model.
 *
 * The site's figures are inline SVG generated by a script — that is the house convention, and it
 * is also what the no-WebGL fallback needs. Because the projection here is the SAME camera maths
 * the WebGL renderer uses and the geometry is the SAME model, a figure cannot drift from the
 * interactive viewer: nothing is redrawn by hand.
 *
 * HIDDEN-LINE REMOVAL. Exact where it can be, honest where it cannot. The hull is a body of
 * revolution, so "is this surface point facing the camera" is an analytic normal test and "is this
 * interior point on the near side" is a dot product against the view direction. That is enough for
 * readable technical linework and it costs nothing. There is no general HLR here and none is
 * claimed: components hidden behind other components may still draw.
 *
 * Runs in node (figure export) and in the browser (fallback) unchanged.
 */

import { hullR, stationX, sectionScale, profileR } from '../model/config.js?v=91301eab';
import { m4lookAt, m4perspective, m4mul, norm, sub, dot, len } from '../core/math.js?v=91301eab';
import { TOKENS, MATERIALS, CATEGORY_TONE } from './palette.js?v=91301eab';

/** Named still views. `ortho` keeps a silhouette a true silhouette. */
export const FIGURE_VIEWS = {
  side: { az: -Math.PI / 2, el: 0, ortho: true, label: 'Side elevation' },
  top: { az: -Math.PI / 2, el: Math.PI / 2 - 0.0001, ortho: true, label: 'Plan' },
  front: { az: Math.PI, el: 0, ortho: true, label: 'Front elevation' },
  'three-quarter': { az: -0.95, el: 0.30, ortho: false, label: 'Three-quarter' },
  'cutaway-three-quarter': { az: -1.25, el: 0.22, ortho: false, label: 'Cutaway three-quarter' },
  underside: { az: -Math.PI / 2, el: -1.25, ortho: false, label: 'Underside' },
};

function cameraFor(cls, viewId, width, height, pad = 0.06) {
  const v = FIGURE_VIEWS[viewId] || FIGURE_VIEWS['three-quarter'];
  const radius = Math.max(cls.lengthM, cls.diameterM) * 0.55;
  const dist = radius * (v.ortho ? 40 : 3.2);
  const eye = [
    dist * Math.cos(v.el) * Math.cos(v.az),
    dist * Math.cos(v.el) * Math.sin(v.az),
    dist * Math.sin(v.el),
  ];
  const view = m4lookAt(eye, [0, 0, 0], [0, 0, 1]);
  const aspect = width / height;
  let proj;
  if (v.ortho) {
    const h = radius * (1 + pad * 2) / Math.min(1, aspect) * 0.92;
    proj = orthoM(h * aspect, h, -dist * 4, dist * 4);
  } else {
    proj = m4perspective(0.36, aspect, radius * 0.05, dist + radius * 8);
  }
  return { eye, vp: m4mul(proj, view), width, height, ortho: v.ortho, label: v.label };
}

function orthoM(hw, hh, near, far) {
  const m = new Float32Array(16);
  m[0] = 1 / hw; m[5] = 1 / hh; m[10] = -2 / (far - near);
  m[14] = -(far + near) / (far - near); m[15] = 1;
  return m;
}

function project(cam, p) {
  const m = cam.vp;
  const x = m[0] * p[0] + m[4] * p[1] + m[8] * p[2] + m[12];
  const y = m[1] * p[0] + m[5] * p[1] + m[9] * p[2] + m[13];
  const w = m[3] * p[0] + m[7] * p[1] + m[11] * p[2] + m[15];
  if (w <= 1e-6) return null;
  return [(x / w * 0.5 + 0.5) * cam.width, (0.5 - y / w * 0.5) * cam.height];
}

/** Is a point ON the hull surface facing the camera? Exact for a body of revolution. */
function hullFacing(cls, p, eye) {
  // Surface normal of r(x)*s(theta) revolved: radial component dominates; the axial slope term
  // keeps the nose and tail correct.
  const theta = Math.atan2(p[2], -p[1]);
  const dx = cls.lengthM * 0.004;
  const r0 = hullR(cls, p[0] - dx), r1 = hullR(cls, p[0] + dx);
  const slope = (r1 - r0) / (2 * dx);
  const rad = [0, -Math.cos(theta), Math.sin(theta)];
  const n = norm([-slope, rad[1], rad[2]]);
  return dot(n, norm(sub(eye, p))) > 0;
}

/** Is an interior point on the near side of the body from this camera? */
function nearSide(cls, p, eye) {
  const toEye = norm(sub(eye, [p[0], 0, 0]));
  return dot([0, p[1], p[2]], toEye) >= -cls.maxRadiusM * 0.05;
}

/* ---------- analytic silhouettes ---------------------------------------------------------------- */

/**
 * The exact outline of the hull in an orthographic view. Analytic, so it is a true silhouette and
 * not a polygon approximation of one.
 */
export function silhouettePath(cls, viewId, cam, samples = 120) {
  const pts = [];
  const upper = [], lower = [];
  for (let i = 0; i <= samples; i++) {
    const t = i / samples;
    const x = stationX(cls, t);
    const r = hullR(cls, x);
    let up, dn;
    if (viewId === 'top') { up = [x, r, 0]; dn = [x, -r, 0]; }
    else { up = [x, 0, r * sectionScale(Math.PI / 2, cls.hull)];
      dn = [x, 0, -r * sectionScale(-Math.PI / 2, cls.hull)]; }
    const a = project(cam, up), bq = project(cam, dn);
    if (a) upper.push(a);
    if (bq) lower.push(bq);
  }
  pts.push(...upper, ...lower.reverse());
  return pts;
}

/* ---------- the figure ---------------------------------------------------------------------------- */

const esc = (s) => String(s).replace(/[&<>"]/g, (c) =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

/**
 * Render one figure.
 *
 * @param {object} b     build() result
 * @param {object} opts  { view, mode, width, height, background, title, caption, cut }
 *   mode: 'exterior' | 'wire' | 'lattice' | 'cutaway' | 'silhouette'
 */
export function staticFigureSVG(b, opts = {}) {
  const cls = b.cls;
  const width = opts.width || 880;
  const height = opts.height || 380;
  const view = opts.view || 'three-quarter';
  const mode = opts.mode || 'wire';
  const cam = cameraFor(cls, view, width, height);
  const bg = opts.background === 'transparent' ? null : (opts.background || TOKENS.bg);
  const out = [];

  out.push(`<svg viewBox="0 0 ${width} ${height}" width="100%" style="height:auto" ` +
    `xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(opts.alt ||
      `${cls.name} conceptual airship, ${(FIGURE_VIEWS[view] || {}).label || view}, ${mode} view`)}">`);
  if (bg) out.push(`<rect width="${width}" height="${height}" fill="${bg}"/>`);

  const cut = opts.cut === undefined ? (mode === 'cutaway' ? 0 : null) : opts.cut;
  const keep = (p) => cut === null || p[1] <= cut;

  /* -- silhouette fill + outline -- */
  if (mode === 'silhouette' || mode === 'exterior' || mode === 'wire' || mode === 'cutaway') {
    if (FIGURE_VIEWS[view] && FIGURE_VIEWS[view].ortho && mode === 'silhouette') {
      const pts = silhouettePath(cls, view, cam);
      out.push(`<path d="${pathD(pts, true)}" fill="${TOKENS.panel}" fill-opacity=".55" ` +
        `stroke="${TOKENS.bone}" stroke-width="1.4"/>`);
    } else {
      // Hull meridians and station rings, back-face culled: readable technical linework.
      const segs = [];
      const nMer = 20, nStn = 90;
      for (let k = 0; k < nMer; k++) {
        const th = (2 * Math.PI * k) / nMer;
        let run = [];
        for (let i = 0; i <= nStn; i++) {
          const t = i / nStn;
          const x = stationX(cls, t);
          const rr = hullR(cls, x) * sectionScale(th, cls.hull);
          const p = [x, -rr * Math.cos(th), rr * Math.sin(th)];
          if (hullFacing(cls, p, cam.eye) && keep(p)) run.push(project(cam, p));
          else { if (run.length > 1) segs.push(run); run = []; }
        }
        if (run.length > 1) segs.push(run);
      }
      for (let i = 0; i <= 16; i++) {
        const t = 0.02 + (0.96 * i) / 16;
        const x = stationX(cls, t);
        const R = hullR(cls, x);
        let run = [];
        for (let j = 0; j <= 72; j++) {
          const th = (2 * Math.PI * j) / 72;
          const rr = R * sectionScale(th, cls.hull);
          const p = [x, -rr * Math.cos(th), rr * Math.sin(th)];
          if (hullFacing(cls, p, cam.eye) && keep(p)) run.push(project(cam, p));
          else { if (run.length > 1) segs.push(run); run = []; }
        }
        if (run.length > 1) segs.push(run);
      }
      out.push(`<path d="${segs.map((s) => pathD(s)).join('')}" fill="none" ` +
        `stroke="${TOKENS.bone}" stroke-opacity=".55" stroke-width="0.7"/>`);
    }
  }

  /* -- structure -- */
  if (mode === 'wire' || mode === 'lattice' || mode === 'cutaway') {
    const structural = ['MacroFrames', 'VacuumLattice', 'SectionJoints'];
    for (const id of structural) {
      const n = b.index.get(id);
      if (!n || !n.geom || n.geom.kind !== 'lines') continue;
      const mat = MATERIALS[n.material] || MATERIALS.lattice;
      const g = n.geom;
      // Bucket by load-path weight, then emit ONE path per bucket. A figure with 12,000 members
      // as individual <line> elements is 300 kB of markup; four bucketed paths is under 40 kB and
      // the visual difference is nil, because the weight only ever reads as four levels anyway.
      const buckets = [[], [], [], []];
      for (let i = 0; i < g.segs; i++) {
        const a = [g.pos[i * 6], g.pos[i * 6 + 1], g.pos[i * 6 + 2]];
        const c = [g.pos[i * 6 + 3], g.pos[i * 6 + 4], g.pos[i * 6 + 5]];
        if (!keep(a) || !keep(c)) continue;
        if (cut === null && !(nearSide(cls, a, cam.eye) && nearSide(cls, c, cam.eye))) continue;
        const pa = project(cam, a), pc = project(cam, c);
        if (!pa || !pc) continue;
        const k = Math.min(3, Math.max(0, Math.floor(g.wid[i * 2] * 4)));
        // Integer precision here, not tenths: a lattice member is one hairline at 880 px, a tenth
        // of a pixel is invisible, and the decimals are a third of the file.
        buckets[k].push(`M${f0(pa[0])} ${f0(pa[1])}L${f0(pc[0])} ${f0(pc[1])}`);
      }
      for (let k = 0; k < 4; k++) {
        if (!buckets[k].length) continue;
        const w = (k + 0.5) / 4;
        out.push(`<path d="${buckets[k].join('')}" stroke="${mat.color}" fill="none" ` +
          `stroke-width="${f2(0.28 + 1.15 * w)}" stroke-opacity="${f2(0.30 + 0.55 * w)}"/>`);
      }
    }
  }

  /* -- component outlines -- */
  if (mode !== 'silhouette') {
    const ce = b.index.get('ComponentEdges');
    if (ce && ce.geom) {
      const g = ce.geom;
      const d = [];
      for (let i = 0; i < g.segs; i++) {
        const a = [g.pos[i * 6], g.pos[i * 6 + 1], g.pos[i * 6 + 2]];
        const c = [g.pos[i * 6 + 3], g.pos[i * 6 + 4], g.pos[i * 6 + 5]];
        if (!keep(a) || !keep(c)) continue;
        // The far side is culled in EVERY mode: an exterior figure showing the machinery on the
        // hidden side is an X-ray, not an exterior.
        if (cut === null && !(nearSide(cls, a, cam.eye) && nearSide(cls, c, cam.eye))) continue;
        if (mode === 'exterior' && !(isOutside(cls, a) || isOutside(cls, c))) continue;
        const pa = project(cam, a), pc = project(cam, c);
        if (!pa || !pc) continue;
        d.push(`M${f0(pa[0])} ${f0(pa[1])}L${f0(pc[0])} ${f0(pc[1])}`);
      }
      if (d.length) {
        // Components draw heavier than the lattice: in a cutaway the machinery is the subject and
        // the structure is the context, and equal weights make both illegible.
        out.push(`<path d="${d.join('')}" stroke="${TOKENS.bone}" stroke-width="1.05" ` +
          `stroke-opacity=".95" fill="none"/>`);
      }
    }
  }

  /* -- caption -- */
  const cap = opts.caption === undefined
    ? `${cls.name} · ${Math.round(cls.lengthM)} m × ${cls.diameterM.toFixed(1)} m · ` +
      `${(cls.displacementM3 / 1000).toLocaleString()} thousand m³ · conceptual reference vehicle`
    : opts.caption;
  if (cap) {
    out.push(`<text x="14" y="${height - 12}" fill="${TOKENS.faint}" font-size="10.5" ` +
      `font-family="ui-monospace,SFMono-Regular,Menlo,monospace">${esc(cap)}</text>`);
  }
  out.push('</svg>');
  return out.join('');
}

function isOutside(cls, p) {
  const r = Math.hypot(p[1], p[2]);
  const theta = Math.atan2(p[2], -p[1]);
  return r >= hullR(cls, p[0]) * sectionScale(theta, cls.hull) * 0.93;
}

const f1 = (v) => Math.round(v * 10) / 10;
const f0 = (v) => Math.round(v);
const f2 = (v) => Math.round(v * 100) / 100;

function pathD(pts, close = false) {
  if (!pts.length) return '';
  const d = [`M${f1(pts[0][0])} ${f1(pts[0][1])}`];
  for (let i = 1; i < pts.length; i++) d.push(`L${f1(pts[i][0])} ${f1(pts[i][1])}`);
  if (close) d.push('Z');
  return d.join(' ');
}

/**
 * The scale-comparison figure: all three classes and physical references in ONE real-metre
 * coordinate system. Nothing here is symbolically enlarged.
 */
export function scaleComparisonSVG(classes, opts = {}) {
  const width = opts.width || 880;
  const rows = [];
  const refs = opts.references === false ? [] : [
    { label: 'Lions Gate Bridge main span', sub: '472 m · Vancouver', lengthM: 472, kind: 'span' },
    { label: 'LZ 129 Hindenburg', sub: 'the largest airship ever flown · 245 m', lengthM: 245, kind: 'ship' },
    { label: 'Boeing 747-400', sub: '70.7 m', lengthM: 70.7, kind: 'plane' },
    { label: 'a person', sub: '1.8 m', lengthM: 1.8, kind: 'person' },
  ];
  for (const c of classes) {
    rows.push({ cls: c, label: c.name, sub: `${c.payloadTonnes.toLocaleString()} t of water · conceptual`,
      lengthM: c.lengthM, diameterM: c.diameterM, kind: 'airship' });
  }
  for (const r of refs) rows.push(r);
  rows.sort((a, b) => b.lengthM - a.lengthM);

  const maxLen = rows[0].lengthM;
  const pad = 16;
  const usable = width - pad * 2 - 8;
  const scale = usable / maxLen;                        // px per metre — one scale for every row

  let y = 26;
  const out = [];
  const parts = [];
  for (const r of rows) {
    const w = r.lengthM * scale;
    const h = r.diameterM ? r.diameterM * scale : Math.max(2, r.lengthM * scale * 0.06);
    parts.push({ r, y, w, h });
    y += Math.max(34, h + 30);
  }
  const height = y + 24;

  out.push(`<svg viewBox="0 0 ${width} ${height}" width="100%" style="height:auto" ` +
    `xmlns="http://www.w3.org/2000/svg" font-family="ui-monospace,SFMono-Regular,Menlo,monospace" ` +
    `role="img" aria-label="${esc(opts.alt || 'The three conceptual airship classes and four ' +
      'physical references drawn to one scale, largest first.')}">`);
  if (opts.background !== 'transparent') {
    out.push(`<rect width="${width}" height="${height}" fill="${TOKENS.bg}"/>`);
  }
  for (const { r, y: ry, w, h } of parts) {
    const colour = r.kind === 'airship' ? TOKENS.warm : TOKENS.faint;
    out.push(`<text x="${pad}" y="${f1(ry - 6)}" fill="${colour}" font-size="11.5" ` +
      `font-weight="600">${esc(r.label)}</text>`);
    out.push(`<text x="${pad + r.label.length * 6.6 + 12}" y="${f1(ry - 6)}" ` +
      `fill="${TOKENS.faint}" font-size="10.5">${esc(r.sub)}</text>`);
    if (r.kind === 'airship') {
      out.push(`<ellipse cx="${f1(pad + w / 2)}" cy="${f1(ry + h / 2)}" rx="${f1(w / 2)}" ` +
        `ry="${f1(h / 2)}" fill="${TOKENS.warm}" fill-opacity=".08" stroke="${TOKENS.warm}" ` +
        `stroke-width="1.5"/>`);
      // The payload itself, as a cube edge-on: the point of the whole figure.
      const cube = Math.cbrt(r.cls.payloadTonnes) * scale;
      out.push(`<rect x="${f1(pad + w / 2 - cube / 2)}" y="${f1(ry + h / 2 - cube / 2)}" ` +
        `width="${f1(Math.max(0.6, cube))}" height="${f1(Math.max(0.6, cube))}" ` +
        `fill="${TOKENS.cool}" fill-opacity=".55" stroke="${TOKENS.cool}" stroke-width="0.8"/>`);
    } else if (r.kind === 'span') {
      out.push(`<line x1="${pad}" y1="${f1(ry + h)}" x2="${f1(pad + w)}" y2="${f1(ry + h)}" ` +
        `stroke="${TOKENS.faint}" stroke-width="2"/>`);
      out.push(`<path d="M${pad} ${f1(ry + h)} Q${f1(pad + w / 2)} ${f1(ry - h * 0.5)} ` +
        `${f1(pad + w)} ${f1(ry + h)}" fill="none" stroke="${TOKENS.faint}" stroke-opacity=".55"/>`);
    } else if (r.kind === 'ship') {
      out.push(`<ellipse cx="${f1(pad + w / 2)}" cy="${f1(ry + h / 2)}" rx="${f1(w / 2)}" ` +
        `ry="${f1(Math.max(2, w * 0.083))}" fill="${TOKENS.faint}" fill-opacity=".12" ` +
        `stroke="${TOKENS.faint}"/>`);
    } else if (r.kind === 'plane') {
      out.push(`<rect x="${pad}" y="${f1(ry + h / 2 - 1.5)}" width="${f1(w)}" height="3" ` +
        `rx="1.5" fill="${TOKENS.muted}" fill-opacity=".5"/>`);
    } else {
      out.push(`<rect x="${pad}" y="${f1(ry)}" width="${f1(Math.max(0.8, w))}" ` +
        `height="${f1(Math.max(1.5, w * 3))}" fill="${TOKENS.bone}"/>`);
    }
  }
  out.push(`<text x="${pad}" y="${height - 8}" fill="${TOKENS.faint}" font-size="10">` +
    `${esc('One scale throughout. The blue square on each airship is its water payload — ' +
      '100 t is a 4.6 m cube. Map symbols elsewhere are enlarged for visibility; this is not.')}` +
    '</text>');
  out.push('</svg>');
  return out.join('');
}

void profileR; void len; void CATEGORY_TONE;
